select p.*, c.name as category_name
from product p
left join category c on c.id = p.category_id

    p.merchant_id = #{merchantId}

        and p.business_type = #{businessType}


        and p.name like concat('%', #{name}, '%')


        and p.category_id = #{categoryId}


        and p.status = #{status}


order by p.id desc

select p.*, c.name as category_name, m.shop_name as shop_name from product p left join category c on c.id = p.category_id left join merchant m on m.id = p.merchant_id
p.status = 1 and m.status = 1
and p.business_type = #{businessType}
and p.merchant_id = #{merchantId}
and p.category_id = #{categoryId}
and p.name like concat('%', #{keyword}, '%')
order by p.sales desc, p.id desc

select p.*, c.name as category_name, m.shop_name as shop_name from product p left join category c on c.id = p.category_id left join merchant m on m.id = p.merchant_id
p.status = 1 and m.status = 1
and p.business_type = #{businessType}
and p.name like concat('%', #{keyword}, '%')
order by rand() limit #{limit}

